using RyanAssets.UI;
using TMPro;
using UnityEngine;
using UnityEngine.UI;

namespace Universes.UniverseData.tower_defense.Client {
    /// <summary>
    /// Tower Defense's screen UI (generated by TD_HudAuthoring): the cash / wave / base status bar, the
    /// next-wave preview, the fast-forward pill, the boss health bar, the tower shop, the focused pad
    /// or tower card, toasts, the wave banner and the end-of-game result with the player's record.
    /// Pure view: <see cref="TD_ClientController"/> feeds it game state.
    /// </summary>
    public sealed class TD_Hud : MonoBehaviour {
        [Header("Status bar")]
        public TMP_Text cashLabel;
        public RectTransform cashPunch;
        public TMP_Text waveTitle, waveStatus;
        public Image waveStatusIcon;
        [Tooltip("Bar fills are sized by their right anchor so rounded ends stay round.")]
        public Image waveProgress, baseFill;
        public TMP_Text baseLabel;
        public RectTransform basePunch;

        [Header("Next wave")]
        public TD_Fader nextWave;
        [Tooltip("Index-aligned with TD_EnemyKind.")]
        public TD_EnemyChip[] enemyChips;
        public TMP_Text readyLabel;
        public Image readyBack;

        [Header("Fast forward")]
        public TD_Fader speedPill;
        public TMP_Text speedLabel;
        public Image speedBack;

        [Header("Boss")]
        public TD_Fader bossPanel;
        public TMP_Text bossLabel;
        [Tooltip("Sized by its right anchor like the other bars.")]
        public Image bossFill;

        [Header("Shop")]
        public TD_ShopCard[] shopCards;
        [Tooltip("Index-aligned with TD_TowerKind; also used by the info card.")]
        public Sprite[] towerPortraits;

        [Header("Focus")]
        public TD_InfoPanel info;
        public TD_Fader prompt;
        public TMP_Text promptLabel;

        [Header("Messages")]
        public TD_Fader toast;
        public Image toastIcon;
        public TMP_Text toastLabel;
        public TD_Fader banner;
        public Image bannerIcon;
        public TMP_Text bannerTitle, bannerSubtitle;
        public TD_Fader result;
        public Image resultIcon;
        public TMP_Text resultTitle, resultSubtitle, resultRecord, resultCountdown;

        [Header("Icons")]
        public Sprite timerIcon, enemiesIcon, coinIcon, baseIcon, readyIcon, waveIcon, trophyIcon, defeatIcon, upgradeIcon;

        [Header("Timing")]
        [Min(0.1f)] public float bannerSeconds = 2.2f;

        [Header("Keys (labels only; the controller reads the keys)")]
        public string readyKey = "R", fastForwardKey = "G";

        int shownCash = -1, shownBase = -1;
        float toastUntil, bannerUntil, cashKick, baseKick;
        UITheme theme;

        void Awake() {
            theme = UITheme.Active;
            for (int i = 0; i < shopCards.Length; i++)
                shopCards[i].Init(TD_Palette.Tower((TD_TowerKind)i), theme.danger, theme.currency);
            toast.Set(false, true);
            banner.Set(false, true);
            result.Set(false, true);
            nextWave.Set(false, true);
            speedPill.Set(false, true);
            bossPanel.Set(false, true);
            prompt.Set(false, true);
            info.fader.Set(false, true);
            waveTitle.text = "TOWER DEFENSE";
            waveStatus.text = "Connecting...";
            Bar(waveProgress, 0f);
            cashLabel.text = "$0";
            baseLabel.text = "";
            resultRecord.text = "";
        }

        void Update() {
            float dt = Time.unscaledDeltaTime;
            if (toast.Visible && Time.unscaledTime > toastUntil) toast.Set(false);
            if (banner.Visible && Time.unscaledTime > bannerUntil) banner.Set(false);
            cashKick = Kick(cashPunch, cashKick, dt);
            baseKick = Kick(basePunch, baseKick, dt);
        }

        static float Kick(RectTransform target, float amount, float dt) {
            if (target == null) return 0f;
            amount = Mathf.MoveTowards(amount, 0f, dt * 2.5f);
            target.localScale = Vector3.one * (1f + 0.18f * amount);
            return amount;
        }

        // ---------------------------------------------------------------- state
        public void ShowState(in TD_StateBroadcast state, bool ready, bool fastVote) {
            if (shownCash >= 0 && state.cash != shownCash) cashKick = 1f;
            if (shownBase >= 0 && state.baseHealth < shownBase) baseKick = 1f;
            shownCash = state.cash;
            shownBase = state.baseHealth;

            cashLabel.text = $"${state.cash:N0}";
            float baseFraction = Mathf.Clamp01(state.baseHealth / (float)TD_Rules.BaseHealth);
            Bar(baseFill, baseFraction);
            baseFill.color = TD_Palette.Health(baseFraction);
            baseLabel.text = $"{Mathf.Max(0, state.baseHealth)}<size=70%><color=#B4BCC8> / {TD_Rules.BaseHealth}</color></size>";

            waveTitle.text = state.phase == TD_Phase.Waiting ? "TOWER DEFENSE" : $"WAVE {state.wave}<size=65%><color=#B4BCC8> / {TD_Rules.WaveCount}</color></size>";
            int total = Mathf.Max(1, TD_Rules.EnemyCount(state.wave));
            switch (state.phase) {
                case TD_Phase.Waiting:
                    Status("Waiting for players", timerIcon, 0f);
                    break;
                case TD_Phase.Build:
                    Status($"Build phase  ·  {state.secondsLeft}s", timerIcon, 1f);
                    break;
                case TD_Phase.Wave:
                    string fast = state.speed > 1f ? $"  ·  {state.speed:0.#}x" : "";
                    Status($"{state.enemiesLeft} {(state.enemiesLeft == 1 ? "enemy" : "enemies")} left{fast}", enemiesIcon, state.enemiesLeft / (float)total);
                    break;
                default:
                    Status(state.phase == TD_Phase.Victory ? "Victory!" : "Base destroyed", state.phase == TD_Phase.Victory ? trophyIcon : defeatIcon, 0f);
                    break;
            }

            ShowNextWave(state, ready);
            ShowSpeed(state, fastVote);
            ShowResult(state);
            if (state.phase != TD_Phase.Wave) bossPanel.Set(false);
        }

        void Status(string text, Sprite icon, float progress) {
            waveStatus.text = text;
            waveStatusIcon.sprite = icon;
            Bar(waveProgress, progress);
        }

        static void Bar(Image fill, float fraction) {
            fill.rectTransform.anchorMax = new Vector2(Mathf.Clamp01(fraction), 1f);
            fill.enabled = fraction > 0.001f;
        }

        void ShowNextWave(in TD_StateBroadcast state, bool ready) {
            bool show = state.phase == TD_Phase.Build;
            nextWave.Set(show);
            if (!show) return;
            var counts = new int[TD_Rules.Enemies.Length];
            foreach (var group in TD_Rules.Wave(state.wave)) counts[(int)group.kind] += group.count;
            for (int i = 0; i < enemyChips.Length && i < counts.Length; i++) {
                enemyChips[i].root.SetActive(counts[i] > 0);
                enemyChips[i].count.text = $"×{counts[i]}";
            }
            int players = Mathf.Max(1, (int)state.activePlayers);
            int bonus = TD_Rules.EarlyStartBonus(state.secondsLeft);
            string reward = bonus > 0 ? $"  <color=#{ColorUtility.ToHtmlStringRGB(theme.currency)}>+${bonus}</color>" : "";
            readyLabel.text = ready
                ? $"Ready{reward}  <color=#B4BCC8>{state.readyPlayers}/{players}</color>"
                : $"<color=#B4BCC8>[{readyKey}]</color>  Start now{reward}  <color=#B4BCC8>{state.readyPlayers}/{players}</color>";
            readyBack.color = ready ? theme.success : theme.surfaceHover;
        }

        void ShowSpeed(in TD_StateBroadcast state, bool fastVote) {
            bool show = state.phase == TD_Phase.Wave;
            speedPill.Set(show);
            if (!show) return;
            bool fast = state.speed > 1f;
            int players = Mathf.Max(1, (int)state.activePlayers);
            speedLabel.text = $"<color=#B4BCC8>[{fastForwardKey}]</color>  {(fast ? $"Fast forward {TD_Rules.FastSpeed:0.#}x" : "Fast forward")}  <color=#B4BCC8>{state.fastPlayers}/{players}</color>";
            speedBack.color = fast ? theme.accent : fastVote ? theme.success : theme.surfaceHover;
        }

        /// <summary>The boss bar: health of the lead boss, and how many are on the road.</summary>
        public void ShowBoss(int count, float health) {
            bossPanel.Set(count > 0);
            if (count <= 0) return;
            string name = TD_Rules.Enemy(TD_EnemyKind.Boss).name.ToUpperInvariant();
            bossLabel.text = count > 1 ? $"{name}  <color=#B4BCC8>×{count}</color>" : name;
            Bar(bossFill, health);
        }

        /// <summary>The player's saved record, shown on the result card.</summary>
        public void ShowRecord(in TD_ProfileBroadcast profile) {
            resultRecord.text = profile.bestWave > 0
                ? $"Personal best: wave {profile.bestWave}  ·  {profile.gamesWon} {(profile.gamesWon == 1 ? "win" : "wins")}  ·  {profile.totalKills:N0} kills"
                : "";
        }

        void ShowResult(in TD_StateBroadcast state) {
            bool over = state.phase is TD_Phase.Victory or TD_Phase.Defeat;
            result.Set(over);
            if (!over) return;
            bool won = state.phase == TD_Phase.Victory;
            resultIcon.sprite = won ? trophyIcon : defeatIcon;
            resultIcon.color = won ? theme.currency : theme.danger;
            resultTitle.text = won ? "VICTORY" : "BASE DESTROYED";
            resultSubtitle.text = won ? $"The base held all {TD_Rules.WaveCount} waves." : $"The defence fell on wave {state.wave}.";
            resultCountdown.text = $"New game in {state.secondsLeft}";
        }

        // ---------------------------------------------------------------- shop + focus
        public void ShowShop(int selected, int cash, bool hasState) {
            for (int i = 0; i < shopCards.Length && i < TD_Rules.Towers.Length; i++)
                shopCards[i].Set(i == selected, !hasState || cash >= TD_Rules.Towers[i].cost);
        }

        public Sprite Portrait(TD_TowerKind kind) => towerPortraits != null && (int)kind < towerPortraits.Length ? towerPortraits[(int)kind] : null;

        public void ShowFocusPad(TD_TowerKind selected, int cash) {
            info.ShowBuild(selected, Portrait(selected), cash);
            var t = TD_Rules.Tower(selected);
            string action = cash >= t.cost ? $"<b>E</b>  Build {t.name}" : $"<color=#{ColorUtility.ToHtmlStringRGB(theme.danger)}>Need ${t.cost - cash} more for a {t.name}</color>";
            Prompt($"{action}     <color=#B4BCC8><b>1-4</b>  Change tower</color>");
        }

        public void ShowFocusTower(in TD_TowerSnap tower, int cash, string sellKey) {
            info.ShowTower(tower, Portrait(tower.kind), cash, sellKey);
            string sell = $"<b>{sellKey}</b>  Sell +${TD_Rules.SellRefund(tower.kind, tower.level)}";
            Prompt(tower.level >= TD_Rules.MaxLevel ? sell : $"<b>E</b>  Upgrade {TD_Rules.Tower(tower.kind).name}     <color=#B4BCC8>{sell}</color>");
        }

        public void ClearFocus() {
            info.Hide();
            prompt.Set(false);
        }

        void Prompt(string text) {
            prompt.Set(text.Length > 0);
            if (text.Length > 0) promptLabel.text = text;
        }

        // ---------------------------------------------------------------- messages
        public enum ToastKind { Info, Good, Bad, Money }

        public void Toast(string message, ToastKind kind, float seconds) {
            toastLabel.text = message;
            (Sprite icon, Color color) = kind switch {
                ToastKind.Good => (readyIcon, theme.success),
                ToastKind.Bad => (baseIcon, theme.danger),
                ToastKind.Money => (coinIcon, theme.currency),
                _ => (upgradeIcon, theme.accent),
            };
            toastIcon.sprite = icon;
            toastIcon.color = color;
            toast.Set(true);
            toastUntil = Time.unscaledTime + seconds;
        }

        public void Banner(string title, string subtitle, bool boss = false) {
            bannerIcon.color = boss ? theme.danger : theme.warning;
            bannerTitle.text = title;
            bannerSubtitle.text = subtitle;
            banner.Set(true);
            bannerUntil = Time.unscaledTime + bannerSeconds;
        }
    }
}
